guidance.correct_example:
import structlog
logger = structlog.get_logger()

def authenticate(a_username: str, a_password: str) -> Result[Token]:
    logger.info('auth_attempt', username=a_username)
    token = verify_credentials(a_username, a_password)
    if token is None:
        return Result.failure('Invalid credentials')
    logger.info('auth_success', username=a_username)
    return Result.success(token)

